package com.example.ausalertshake;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.hardware.*;import android.media.*;import android.os.*;
public class ShakeService extends Service implements SensorEventListener {
 SensorManager sm; Sensor sensor; PowerManager.WakeLock lock; ToneGenerator tone; MediaPlayer player; Vibrator vibrator; Handler handler=new Handler(Looper.getMainLooper());
 final float[] gravity=new float[3]; boolean ready=false,active=false,pending=false; int axis=-1,sign=0,count=0; long first=0,last=0,trigger=0,start=0,aboveSince=0;
 Runnable sound; static final long WINDOW=1500,COOLDOWN=30000;
 void disableDndForMonitoring(){try{if(!getSharedPreferences("MainActivity",MODE_PRIVATE).getBoolean("dnd_override",false))return;NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(nm==null||!nm.isNotificationPolicyAccessGranted())return;android.content.SharedPreferences prefs=getSharedPreferences("dnd_state",MODE_PRIVATE);if(!prefs.getBoolean("saved",false))prefs.edit().putBoolean("saved",true).putInt("original",nm.getCurrentInterruptionFilter()).apply();nm.setInterruptionFilter(NotificationManager.INTERRUPTION_FILTER_ALL);}catch(Exception ignored){}}
 void restoreDnd(){try{android.content.SharedPreferences prefs=getSharedPreferences("dnd_state",MODE_PRIVATE);if(!prefs.getBoolean("saved",false))return;NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(nm!=null&&nm.isNotificationPolicyAccessGranted())nm.setInterruptionFilter(prefs.getInt("original",NotificationManager.INTERRUPTION_FILTER_ALL));prefs.edit().clear().apply();}catch(Exception ignored){}}
 void maximizeAlarmVolume(){try{AudioManager am=(AudioManager)getSystemService(AUDIO_SERVICE);if(am==null)return;android.content.SharedPreferences prefs=getSharedPreferences("alarm_volume",MODE_PRIVATE);if(!prefs.getBoolean("saved",false)){prefs.edit().putInt("original",am.getStreamVolume(AudioManager.STREAM_ALARM)).putBoolean("saved",true).apply();}am.setStreamVolume(AudioManager.STREAM_ALARM,am.getStreamMaxVolume(AudioManager.STREAM_ALARM),0);}catch(Exception ignored){}}
 void restoreAlarmVolume(){try{android.content.SharedPreferences prefs=getSharedPreferences("alarm_volume",MODE_PRIVATE);if(!prefs.getBoolean("saved",false))return;AudioManager am=(AudioManager)getSystemService(AUDIO_SERVICE);if(am!=null)am.setStreamVolume(AudioManager.STREAM_ALARM,prefs.getInt("original",am.getStreamVolume(AudioManager.STREAM_ALARM)),0);prefs.edit().remove("saved").remove("original").apply();}catch(Exception ignored){}}
 @Override public void onCreate(){super.onCreate();sm=(SensorManager)getSystemService(SENSOR_SERVICE);sensor=sm.getDefaultSensor(Sensor.TYPE_ACCELEROMETER);vibrator=(Vibrator)getSystemService(VIBRATOR_SERVICE);NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("monitor","Shake monitor",NotificationManager.IMPORTANCE_LOW));NotificationChannel alerts=new NotificationChannel("shake_alerts","Detected shake alarms",NotificationManager.IMPORTANCE_HIGH);alerts.setSound(null,null);alerts.enableVibration(false);nm.createNotificationChannel(alerts);}
 Notification alertNotice(){Intent stopIntent=new Intent(this,ShakeService.class).setAction("STOP");PendingIntent stopPi=PendingIntent.getService(this,2,stopIntent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent openPi=PendingIntent.getActivity(this,3,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,"shake_alerts").setSmallIcon(android.R.drawable.ic_dialog_alert).setColor(0xffff3048).setColorized(true).setContentTitle("AusAlert — shake detected").setContentText("Alarm active • tap Stop Alarm to silence").setContentIntent(openPi).addAction(android.R.drawable.ic_media_pause,"Stop Alarm",stopPi).setAutoCancel(false).build();}
 Notification notice(){Intent stopIntent=new Intent(this,ShakeService.class).setAction("OFF");PendingIntent stopPi=PendingIntent.getService(this,1,stopIntent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent pi=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,"monitor").setSmallIcon(android.R.drawable.ic_dialog_alert).setContentTitle("AusAlert monitoring").setContentText("Shake detector running • unofficial demo").setContentIntent(pi).addAction(android.R.drawable.ic_media_pause,"Stop monitoring",stopPi).setOngoing(true).build();}
 @Override public int onStartCommand(Intent i,int f,int id){String a=i==null?"START":i.getAction();if("OFF".equals(a)){active=false;getSharedPreferences("MainActivity",MODE_PRIVATE).edit().putBoolean("armed",false).apply();stopSound();restoreAlarmVolume();restoreDnd();sm.unregisterListener(this);stopSelf();return START_NOT_STICKY;}if("STOP".equals(a)){stopSound();trigger=SystemClock.elapsedRealtime();reset();if(!active){restoreAlarmVolume();stopSelf();}return START_NOT_STICKY;}if("TEST".equals(a)){maximizeAlarmVolume();if(Build.VERSION.SDK_INT>=34)startForeground(1,notice(),ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE);else startForeground(1,notice());alarm();return START_NOT_STICKY;}if(sensor==null){stopSelf();return START_NOT_STICKY;}if(Build.VERSION.SDK_INT>=34)startForeground(1,notice(),ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE);else startForeground(1,notice());active=true;disableDndForMonitoring();maximizeAlarmVolume();start=SystemClock.elapsedRealtime();sm.unregisterListener(this);boolean registered=sm.registerListener(this,sensor,SensorManager.SENSOR_DELAY_GAME);if(!registered){active=false;stopSelf();return START_NOT_STICKY;}PowerManager pm=(PowerManager)getSystemService(POWER_SERVICE);if(lock==null){lock=pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"AusAlert:shake");lock.acquire();}return START_STICKY;}
 void stopSound(){((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancel(2);pending=false;handler.removeCallbacksAndMessages(null);if(player!=null){try{player.stop();}catch(Exception ignored){}player.release();player=null;}if(tone!=null){tone.stopTone();tone.release();tone=null;}if(vibrator!=null)vibrator.cancel();}
 void startVibration(){if(vibrator!=null&&vibrator.hasVibrator()){long[] pattern={0,450,200,450,200,450,350};vibrator.vibrate(VibrationEffect.createWaveform(pattern,0));}}
 void playFallbackLoop(){startVibration();tone=new ToneGenerator(AudioManager.STREAM_ALARM,90);Runnable[] cycle=new Runnable[1];cycle[0]=()->{if(tone==null)return;for(int n=0;n<6;n++){final int index=n;handler.postDelayed(()->{if(tone!=null)tone.startTone(ToneGenerator.TONE_PROP_BEEP,850);},index*1250L);}handler.postDelayed(cycle[0],7500);};cycle[0].run();}
 void playLoop(){try{maximizeAlarmVolume();int id=R.raw.alarm;player=new MediaPlayer();player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build());android.content.res.AssetFileDescriptor afd=getResources().openRawResourceFd(id);try{player.setDataSource(afd.getFileDescriptor(),afd.getStartOffset(),afd.getLength());}finally{afd.close();}player.setLooping(true);player.prepare();player.start();startVibration();}catch(Exception e){if(player!=null){player.release();player=null;}playFallbackLoop();}}
 void alarm(){if(!active && !getSharedPreferences("MainActivity",MODE_PRIVATE).getBoolean("armed",false)){/* Test alarm remains available when monitoring is off. */}stopSound();pending=true;trigger=SystemClock.elapsedRealtime();sound=()->{if(!pending)return;pending=false;playLoop();((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(2,alertNotice());};handler.postDelayed(sound,1000);}
 void reset(){axis=-1;sign=0;count=0;first=0;aboveSince=0;}
 @Override public void onSensorChanged(SensorEvent e){long now=SystemClock.elapsedRealtime();float[] v=new float[3];for(int j=0;j<3;j++){if(!ready)gravity[j]=e.values[j];gravity[j]=.85f*gravity[j]+.15f*e.values[j];v[j]=e.values[j]-gravity[j];}ready=true;if(!active||pending||now-start<2000||now-trigger<COOLDOWN){aboveSince=0;return;}
 float magnitude=(float)Math.sqrt(v[0]*v[0]+v[1]*v[1]+v[2]*v[2]);
 int sensitivity=Math.max(20,Math.min(100,getSharedPreferences("MainActivity",MODE_PRIVATE).getInt("sensitivity",60)));
 // Three-axis linear acceleration: lower thresholds at higher sensitivity.
 // A short sustained signal reduces single-sample noise false alarms.
 float threshold=0.12f+(100-sensitivity)*0.035f;
 if(magnitude>=threshold){if(aboveSince==0)aboveSince=now;if(now-aboveSince>=120){aboveSince=0;alarm();}}
 else aboveSince=0;}
 @Override public void onAccuracyChanged(Sensor s,int a){}
 @Override public void onDestroy(){active=false;sm.unregisterListener(this);stopSound();restoreAlarmVolume();restoreDnd();if(lock!=null&&lock.isHeld())lock.release();super.onDestroy();}
 @Override public IBinder onBind(Intent i){return null;}
}